/**
 * components/ui/modal.tsx
 *
 * Centred dialog — focus-trapped, scroll-lock safe.
 */
import { X } from 'lucide-react'
import * as React from 'react'

import { Portal } from '~/components/primitives/portal'
import { useLatest } from '~/hooks/use-latest'
import { cx } from '~/lib/cx'
import { lockBodyScroll, trapFocus } from '~/lib/overlay'
import styles from './modal.module.scss'

export type ModalSize = 'sm' | 'md' | 'lg' | 'xl' | 'full'

const SIZE: Record<ModalSize, string> = {
  sm: styles.sizeSm,
  md: styles.sizeMd,
  lg: styles.sizeLg,
  xl: styles.sizeXl,
  full: styles.sizeFull,
}

export interface ModalProps {
  open: boolean
  onClose: () => void
  title?: string
  /** Required for a11y when `title` is omitted. */
  'aria-label'?: string
  size?: ModalSize
  hideClose?: boolean
  className?: string
  children?: React.ReactNode
  footer?: React.ReactNode
}

export function Modal({
  open,
  onClose,
  title,
  'aria-label': ariaLabel,
  size = 'md',
  hideClose,
  className,
  children,
  footer,
}: ModalProps) {
  const titleId = React.useId()
  const [panel, setPanel] = React.useState<HTMLDivElement | null>(null)
  const onCloseRef = useLatest(onClose)

  React.useEffect(() => {
    if (!open || !panel) return
    const unlock = lockBodyScroll()
    const releaseTrap = trapFocus(panel, () => onCloseRef.current())
    return () => {
      releaseTrap()
      unlock()
    }
  }, [open, panel, onCloseRef])

  if (!open) return null

  return (
    <Portal>
      <div className={styles.root}>
        <div
          className={styles.overlay}
          aria-hidden="true"
          onClick={() => onCloseRef.current()}
        />

        <div
          ref={setPanel}
          role="dialog"
          aria-modal="true"
          aria-labelledby={title ? titleId : undefined}
          aria-label={!title ? (ariaLabel ?? 'Dialog') : undefined}
          tabIndex={-1}
          className={cx(styles.panel, SIZE[size], className)}
          onClick={(event) => event.stopPropagation()}
        >
          {title || !hideClose ? (
            <div className={styles.header}>
              {title ? (
                <h2 id={titleId} className={styles.title}>
                  {title}
                </h2>
              ) : null}

              {hideClose ? null : (
                <button
                  type="button"
                  className={styles.close}
                  onClick={() => onCloseRef.current()}
                  aria-label="Close"
                >
                  <X aria-hidden />
                </button>
              )}
            </div>
          ) : null}

          <div className={styles.body}>{children}</div>

          {footer ? <div className={styles.footer}>{footer}</div> : null}
        </div>
      </div>
    </Portal>
  )
}

@use 'styles' as vz;

.root {
  position: fixed;
  inset: 0;
  z-index: vz.z('modal');
  display: flex;
  align-items: center;
  justify-content: center;
  padding: vz.space(4);
}

.overlay {
  position: absolute;
  inset: 0;
  background: vz.color('foreground', 0.45);
  backdrop-filter: blur(6px);
  animation: vz-modal-overlay-in vz.duration('base') vz.ease('out') both;

  @include vz.motion-reduce {
    animation: none;
  }
}

.panel {
  position: relative;
  display: flex;
  flex-direction: column;
  width: 100%;
  max-height: 90vh;
  border: 1px solid vz.color('border', 0.8);
  border-radius: vz.radius('2xl');
  background: vz.color('card');
  color: vz.color('card-foreground');
  box-shadow: vz.elevation(3);
  outline: none;
  animation: vz-modal-in vz.duration('slow') vz.ease('out') both;

  @include vz.motion-reduce {
    animation: none;
  }
}

.size-sm {
  max-width: 24rem;
}

.size-md {
  max-width: 28rem;
}

.size-lg {
  max-width: 32rem;
}

.size-xl {
  max-width: 42rem;
}

.size-full {
  max-width: 95vw;
}

.header {
  display: flex;
  flex: none;
  align-items: center;
  justify-content: space-between;
  gap: vz.space(3);
  padding: vz.space(4) vz.space(6);
  border-bottom: 1px solid vz.color('border');
}

.title {
  margin: 0;
  color: vz.color('foreground');
  font-size: vz.font-size('base');
  font-weight: 600;
  line-height: 1.3;
  letter-spacing: -0.01em;
}

.close {
  display: inline-flex;
  flex: none;
  align-items: center;
  justify-content: center;
  width: vz.space(8);
  height: vz.space(8);
  margin-inline-start: auto;
  padding: 0;
  border: 0;
  border-radius: vz.radius('md');
  background: transparent;
  color: vz.color('muted-foreground');
  cursor: pointer;
  transition:
    background-color vz.duration('fast') vz.ease('out'),
    color vz.duration('fast') vz.ease('out');

  @include vz.hover {
    background: vz.color('muted');
    color: vz.color('foreground');
  }

  @include vz.focus-ring(2px, 2px, 0.6);

  svg {
    @include vz.icon(4);
  }
}

.body {
  flex: 1;
  padding: vz.space(4) vz.space(6);
  overflow-y: auto;

  @include vz.overscroll;
  @include vz.scrollbar(8px);
}

.footer {
  flex: none;
  padding: vz.space(4) vz.space(6);
  border-top: 1px solid vz.color('border');
}

@keyframes vz-modal-overlay-in {
  from {
    opacity: 0;
  }

  to {
    opacity: 1;
  }
}

@keyframes vz-modal-in {
  from {
    opacity: 0;
    transform: translateY(8px) scale(0.98);
  }

  to {
    opacity: 1;
    transform: none;
  }
}
